@Composable fun CalendarWorkspace(api:ApiClient,data:StudentData,onExpired:()->Unit,open:(String)->Unit){
    var mode by rememberSaveable{mutableStateOf("Calendar")};var year by rememberSaveable{mutableIntStateOf(data.today().year)};var revision by remember{mutableIntStateOf(0)};var edit by remember{mutableStateOf<JSONObject?>(null)}
    Column{FilterChips(listOf("Calendar","Holidays"),mode){mode=it};if(mode=="Calendar")StudentCalendarScreen(data,api,null,onExpired,open)else RemotePanel(api,"workspace/holidays.php?year=$year&revision=$revision",onExpired){json->LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(14.dp)){
        item{PageTitle("Philippine holidays","National holidays and campus no-class decisions are separate.");SearchSelect("Year",year.toString(),(data.today().year-2..data.today().year+2).map{it.toString() to it.toString()}){year=it.toInt()};Text(json.text("notice"),style=MaterialTheme.typography.bodySmall)}
        items((json.optJSONArray("events")?:JSONArray()).objects()){row->val tags=row.optJSONObject("customTags")?:JSONObject();Panel{Text(row.text("title"),style=MaterialTheme.typography.titleMedium);Text(tags.text("date"));Text(tags.text("typeLabel"));Text(if(tags.optBoolean("noClasses"))"Campus no-class day"else"Normal campus scheduling applies");if(tags.optBoolean("editable"))TextButton(onClick={edit=tags}){Text("Change campus decision")}}}
    }}}
    edit?.let{tags->NativeEditor("Campus holiday decision",listOf(NativeField("no_classes","Campus schedule",if(tags.optBoolean("noClasses"))"1"else"0",listOf("0" to "Follow normal schedule","1" to "No classes"))),onExpired,{edit=null},"Save decision",extra={Text("${tags.text("date")} · Existing attendance history is preserved.")}){input->api.post("workspace/holidays.php",input.put("date",tags.text("date")).put("holiday_key",tags.text("holidayKey")).put("year",year));revision++}}
}

@Composable fun RecollectionsWorkspace(api:ApiClient,data:StudentData?,onExpired:()->Unit,open:((String)->Unit)?=null){var query by rememberSaveable{mutableStateOf("")};var page by rememberSaveable(query){mutableIntStateOf(1)};var revision by remember{mutableIntStateOf(0)};var edit by remember{mutableStateOf<JSONObject?>(null)};var detail by remember{mutableStateOf<JSONObject?>(null)};var attendance by remember{mutableStateOf(false)};var control by remember{mutableStateOf("")};var selected by remember{mutableStateOf(setOf<Long>())};var record by remember{mutableStateOf(false)};var person by remember{mutableStateOf<JSONObject?>(null)};var picking by remember{mutableStateOf(false)};if(picking)AccountPicker(api,onExpired,{picking=false}){person=it}
    if(attendance&&detail!=null){Column{TextButton(onClick={attendance=false}){Text("Back to activity")};RemotePanel(api,"workspace/recollections.php?mode=attendance&id=${detail?.text("id")}&page=$page&revision=$revision",onExpired){json->LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(12.dp)){item{PageTitle("Activity attendance","Recorded participants and manual corrections.");Button(onClick={record=true}){Text("Record attendance")}};items((json.optJSONArray("items")?:JSONArray()).objects()){row->Panel{Text(row.text("name"),style=MaterialTheme.typography.titleMedium);Text(row.text("school_id"));StatusPill(row.text("status"));Text("${row.text("time_in")} · ${row.text("source")}")}};item{PageControls(page,json.optInt("pages",1),json.optInt("total")){page=it}}}}};if(record)NativeEditor("Record activity attendance",listOf(NativeField("status","Status","Attended",listOf("Attended","Late","Absent","Excused").map{it to it}),NativeField("reason","Reason",required=true)),onExpired,{record=false},extra={OutlinedButton(onClick={picking=true}){Text(person?.let{"${it.text("name")} · ${it.text("school_id")}"}?:"Select participant")}}){input->require(person!=null){"Select a participant."};api.post("workspace/recollections.php",input.put("user_id",person?.optLong("id")).put("action","attendance").put("id",detail?.optLong("id")));revision++};return}
    RemotePanel(api,"workspace/recollections.php?q=${encoded(query)}&page=$page&revision=$revision",onExpired){json->LazyColumn(contentPadding=pagePadding,verticalArrangement=Arrangement.spacedBy(14.dp)){
        item{PageTitle("Recollections & retreats","Formation activities and multi-day schedules.");if(json.optBoolean("can_manage"))Button(onClick={edit=JSONObject()}){Text("Create activity")};OutlinedTextField(query,{query=it},label={Text("Search activity or venue")},singleLine=true,modifier=Modifier.fillMaxWidth())}
        if(json.optBoolean("can_manage"))item{BulkDeleteControl(api,"recollection",selected,{selected=it},onExpired,open){revision++}}
        items((json.optJSONArray("items")?:JSONArray()).objects()){row->Card(onClick={detail=row},modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(18.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){if(json.optBoolean("can_manage"))Checkbox(row.optLong("id") in selected,{yes->selected=if(yes&&selected.size<100)selected+row.optLong("id")else selected-row.optLong("id")});Text(row.text("title"),style=MaterialTheme.typography.titleLarge);StatusPill(row.text("type"));Text("${eventDates(row.text("date"),row.text("end_date"))}");Text("${scheduleTime(row.text("start_time"))} \u2013 ${scheduleTime(row.text("end_time"))}");Text(row.text("venue"));Text("Facilitator: ${row.text("facilitator").ifBlank{"Not specified"}}",style=MaterialTheme.typography.bodySmall)}}}
        item{PageControls(page,json.optInt("pages",1),json.optInt("total")){page=it}}
    }}
    detail?.let{row->AlertDialog(onDismissRequest={detail=null},title={Text(row.text("title"))},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Text(row.text("venue"));Text("${eventDates(row.text("date"),row.text("end_date"))}");Text("${scheduleTime(row.text("start_time"))} \u2013 ${scheduleTime(row.text("end_time"))}");Text("Facilitator: ${row.text("facilitator")}");StatusPill(row.text("status"));if(api.can("manage_recollections")){TextButton(onClick={edit=row;detail=null}){Text("Edit")};TextButton(onClick={attendance=true}){Text("View attendance")};TextButton(onClick={control="status"}){Text("Change status")};TextButton(onClick={control="delete"}){Text("Delete activity")}}}},confirmButton={TextButton(onClick={detail=null}){Text("Close")}})}
    if(control.isNotBlank()&&detail!=null)NativeEditor(if(control=="delete")"Delete activity?"else"Activity status",if(control=="delete")emptyList()else listOf(NativeField("status","Status",detail?.text("status").orEmpty(),listOf("scheduled","open","closed","cancelled").map{it to it})),onExpired,{control=""},"Confirm"){input->api.post("workspace/recollections.php",input.put("id",detail?.optLong("id")).put("action",control));detail=null;revision++}
    edit?.let{row->RecollectionEditor(api,row,onExpired,{edit=null}){revision++}}
}
